fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> bool {
    for &item in list1 {
        if contains(list2, item) {
            return true;
        }
    }
    false
}

fn contains(list: &Vec<i32>, element: i32) -> bool {
    for &item in list {
        if item == element {
            return true;
        }
    }
    false
}

